func agentWriteHookLabel(eventType agent.EventType, claudePostTodoCheckpointHook bool) string {
	switch {
	case claudePostTodoCheckpointHook:
		return "post-todo"
	case eventType == agent.SubagentEnd:
		return "subagent-end"
	default:
		return "turn-end"
	}
}

